        let m1 = v[0] * v[1];
        let m2 = v[0] * v[2];
        let m3 = v[0] * v[3];
        let m4 = m1 * T::from_i64(2);
        let m5 = m2 * T::from_i64(2);
        let m6 = m3 * T::from_i64(2);
        let m7 = -m5;
        let m8 = -m6;
        let m9 = -m4;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Multivector { c: [(x[0].scale(m0)).0, (x[1].scale(m0) + x[2].scale(m4) + x[3].scale(m5) + x[4].scale(m6)).0, (x[2].scale(m0)).0, (x[3].scale(m0)).0, (x[4].scale(m0)).0, (x[5].scale(m0) + x[8].scale(m7) + x[9].scale(m6)).0, (x[6].scale(m0) + x[8].scale(m4) + x[10].scale(m8)).0, (x[7].scale(m0) + x[9].scale(m9) + x[10].scale(m5)).0, (x[8].scale(m0)).0, (x[9].scale(m0)).0, (x[10].scale(m0)).0, (x[11].scale(m0) + x[14].scale(m8)).0, (x[12].scale(m0) + x[14].scale(m7)).0, (x[13].scale(m0) + x[14].scale(m9)).0, (x[14].scale(m0)).0, (x[15].scale(m0)).0] }
